```javascript
import {
  Group, Mesh, PlaneGeometry, PointLight, Color, MeshBasicNodeMaterial
} from 'three/webgpu';
import { uv, vec3, mix, color, smoothstep, length, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- backdrop gradient plane ---
  const backdropGeo = new PlaneGeometry(3.6, 2.4);
  const inkColor = color(colors.ink);
  const paperColor = color(colors.paper);
  const gradientNode = mix(paperColor, inkColor, uv.y);  // paper top → ink bottom
  const backdropMat = new MeshBasicNodeMaterial({ colorNode: gradientNode });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.6);
  group.add(backdrop);

  // --- load gear mesh ---
  ctx.glbLoader.loadGLB(config.meshUrl).then(gltf => {
    group.add(gltf.scene);
    // optional: adjust materials for PBR consistency
    gltf.scene.traverse(child => {
      if (child.isMesh && child.material) {
        child.material.roughness = Math.max(child.material.roughness ?? 0.5, 0.5);
        child.material.metalness = Math.min(child.material.metalness ?? 0.5, 0.55);
      }
    });
  });

  // --- contact shadow plane ---
  const shadowGeo = new PlaneGeometry(2.8, 2.8);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    colorNode: vec3(0, 0, 0),
    opacityNode: smoothstep(1.0, 0.0, length(uv - vec3(0.5, 0.5, 0.0)) * 2.0) // radial fade
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.05, 0);
  group.add(shadow);

  // --- lighting ---
  const keyLight = new PointLight(new Color(0xffffff), 1.2);
  keyLight.position.set(2.5, 2.5, 3);
  group.add(keyLight);

  const rimLight = new PointLight(new Color(colors.paper), 0.8);
  rimLight.position.set(-2.5, -1.5, 2.5);
  group.add(rimLight);

  const fillLight = new PointLight(new Color(colors.paper), 0.3);
  fillLight.position.set(0, -2, 1);
  group.add(fillLight);

  // --- interaction state ---
  let hoverTween = null;
  let clickTween = null;
  const baseY = 0; // adapter will position the group

  group.userData.handlers = {
    onPointerOver: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: baseY + 0.15,
        duration: 0.35,
        ease: 'power3.out'
      });
    },
    onPointerOut: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: baseY,
        duration: 0.35,
        ease: 'power3.out'
      });
    },
    onClick: () => {
      ctx.emit('hub-home.select', { nodeId: config.id });
      if (clickTween) clickTween.kill();
      clickTween = gsap.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1, y: 1, z: 1,
            duration: 0.2,
            ease: 'power4.out'
          });
        }
      });
    }
  };

  // --- cleanup ---
  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (clickTween) clickTween.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    // dispose GLB resources if needed (traverse and dispose)
    group.traverse(child => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else if (child.material) {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
